agent-browser run - <<'JS'
page.goto("https://www.gov.uk/bank-holidays");
return page.evaluate(() => {
  const out = {};
  for (const id of ["england-and-wales","scotland","northern-ireland"]) {
    const s=document.getElementById(id);
    const t=s.innerText;
    out[id]=[(t.match(/\b2027\b/g)||[]).length, t.length];
    const tabs=[...s.querySelectorAll("table")].map(x=>x.querySelector("caption")?.innerText+"|"+x.querySelectorAll("tbody tr").length);
    out[id+"t"]=tabs;
  }
  return out;
});
